document.querySelectorAll('[data-lab="G03-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='true';const zh=root.dataset.lang==='zh';const descriptions={NVT:zh?['N、V保持固定；温控表示与热环境交换能量，温度围绕目标涨落。','观察温度、动能与结构变化；固定体积决定盒子密度不随压控调整。']:['N and V are fixed; a thermostat represents heat exchange and temperature fluctuates around its target.','Observe temperature, kinetic energy, and structure. Fixed volume prevents barostat-driven density adjustment.'],NPT:zh?['N保持固定；温控和压控共同作用，体积可以变化。','观察体积、密度与温度的联合变化，保留体积涨落。']:['N is fixed; temperature and pressure coupling act together, allowing volume to change.','Observe volume, density, and temperature together, retaining volume fluctuations.'],NVE:zh?['N、V固定，撤去温控与压控，检查近似孤立动力学。','观察总能量的波动与漂移；动能与势能之间仍可相互转换。']:['N and V are fixed, with thermostat and barostat removed for approximately isolated dynamics.','Observe total-energy fluctuations and drift; kinetic and potential energy can still exchange.']};function set(s){root.querySelectorAll('[data-stage]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.stage===s)));root.querySelector('[data-heat]').setAttribute('opacity',s==='NVE'?'0.15':'1');root.querySelector('[data-pressure]').setAttribute('opacity',s==='NPT'?'1':'0.15');root.querySelector('[data-box]').setAttribute('stroke-dasharray',s==='NPT'?'7 4':'none');root.querySelector('[data-state]').textContent=descriptions[s][0];root.querySelector('[data-observation]').textContent=descriptions[s][1];}root.querySelectorAll('[data-stage]').forEach(b=>b.addEventListener('click',()=>set(b.dataset.stage)));root.querySelector('[data-reset]').addEventListener('click',()=>set('NVT'));set('NVT');});